insert into public.listings (id, title, description, price, category, condition, seller_email, image_url, location, created_at)
values
  ('a0000000-0000-4000-8000-000000000001', 'MacBook Pro 14-inch (M3 Pro, 18GB, 512GB)', 'Bought last year, battery cycle count under 120. No scratches or dents. Comes with the original 70W charger and box. Factory reset and ready to go.', 890.00, 'Electronics', 'Used - Like New', 'demo.seller1@example.com', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=1200&q=80', 'Palo Alto, CA', now() - interval '3 hours'),
  ('a0000000-0000-4000-8000-000000000002', 'Sony Mirrorless Camera Kit with 2 Lenses', 'Sony mirrorless body with the 16-50mm kit lens and a 50mm f/1.8 prime. Two batteries, charger, and a 64GB SD card. About 8,000 shutter count.', 650.00, 'Electronics', 'Used - Good', 'demo.seller2@example.com', 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=1200&q=80', 'Redwood City, CA', now() - interval '6 hours'),
  ('a0000000-0000-4000-8000-000000000003', 'iPad Pro 11-inch with Apple Pencil', 'Wi-Fi, 128GB, Space Gray. Screen protector on since day one. Includes 2nd-gen Apple Pencil, USB-C charger and a folio case.', 520.00, 'Electronics', 'Used - Like New', 'demo.seller3@example.com', 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=1200&q=80', 'Palo Alto, CA', now() - interval '10 hours'),
  ('a0000000-0000-4000-8000-000000000004', 'Wireless Noise-Cancelling Headphones', 'Over-ear Bluetooth headphones with active noise cancelling and about 30 hours of battery. Includes carrying case, USB-C cable and audio cable.', 180.00, 'Electronics', 'Used - Like New', 'demo.seller4@example.com', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=1200&q=80', 'Menlo Park, CA', now() - interval '14 hours'),
  ('a0000000-0000-4000-8000-000000000005', 'Industrial Grey Floor Lamp', 'Matte grey metal floor lamp with an adjustable shade, 60 inches tall. Takes a standard E26 bulb (LED bulb included).', 35.00, 'Home Goods', 'Used - Like New', 'demo.seller2@example.com', 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=1200&q=80', 'San Mateo, CA', now() - interval '26 hours'),
  ('a0000000-0000-4000-8000-000000000006', 'Green Velvet Three-Seat Sofa', 'Mid-century style sofa in emerald velvet with walnut legs, 84 inches wide. Pet-free, smoke-free home. Light wear on one cushion. Legs unscrew for moving; you pick up.', 480.00, 'Home Goods', 'Used - Good', 'demo.seller1@example.com', 'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?auto=format&fit=crop&w=1200&q=80', 'Menlo Park, CA', now() - interval '30 hours'),
  ('a0000000-0000-4000-8000-000000000007', 'Round White Dining Table with 2 Chairs', '35-inch round white table with beech legs and two matching molded chairs. Seats two comfortably, four in a pinch. Small scuff on one chair leg.', 140.00, 'Home Goods', 'Used - Good', 'demo.seller3@example.com', 'https://images.unsplash.com/photo-1533090481720-856c6e3c1fdc?auto=format&fit=crop&w=1200&q=80', 'Mountain View, CA', now() - interval '36 hours'),
  ('a0000000-0000-4000-8000-000000000008', 'Birch Wood Bar Stool', 'Solid birch counter-height stool, 25 inches to the seat. Sturdy with no wobble. Works as a plant stand too.', 25.00, 'Home Goods', 'Used - Good', 'demo.seller4@example.com', 'https://images.unsplash.com/photo-1503602642458-232111445657?auto=format&fit=crop&w=1200&q=80', 'Redwood City, CA', now() - interval '40 hours'),
  ('a0000000-0000-4000-8000-000000000009', 'Acoustic Guitar with Gig Bag', 'Full-size dreadnought acoustic, solid spruce top. Recently restrung with light-gauge strings, low action, no buzz. Includes padded gig bag, tuner and capo.', 160.00, 'Musical Instruments', 'Used - Good', 'demo.seller2@example.com', 'https://images.unsplash.com/photo-1510915361894-db8b60106cb1?auto=format&fit=crop&w=1200&q=80', 'Menlo Park, CA', now() - interval '48 hours'),
  ('a0000000-0000-4000-8000-000000000010', 'Aluminum Road Bike, 54cm Frame', 'Shimano 105 groupset, 22 speeds. New chain and bar tape this fall, tires have plenty of tread left. Fits riders about 5''6" to 5''10". Pedals not included.', 420.00, 'Vehicles', 'Used - Good', 'demo.seller1@example.com', 'https://images.unsplash.com/photo-1541625602330-2277a4c46182?auto=format&fit=crop&w=1200&q=80', 'Mountain View, CA', now() - interval '52 hours'),
  ('a0000000-0000-4000-8000-000000000011', 'Olympic Barbell with 160 lb of Plates', '7 ft, 45 lb Olympic bar plus iron plates (2x45, 2x25, 2x10). Spring collars included. Some surface rust on the plates, bar sleeves spin smoothly.', 280.00, 'Sporting Goods', 'Used - Good', 'demo.seller3@example.com', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=1200&q=80', 'Sunnyvale, CA', now() - interval '60 hours'),
  ('a0000000-0000-4000-8000-000000000012', 'Nintendo Switch with 3 Games', 'Switch console with neon Joy-Cons, dock and charger. Includes Mario Kart 8 Deluxe, Animal Crossing and Zelda: Breath of the Wild. No drift.', 230.00, 'Toys & Games', 'Used - Good', 'demo.seller4@example.com', 'https://images.unsplash.com/photo-1578303512597-81e6cc155b3e?auto=format&fit=crop&w=1200&q=80', 'Sunnyvale, CA', now() - interval '66 hours'),
  ('a0000000-0000-4000-8000-000000000013', 'Polaroid OneStep 2 Instant Camera', 'White OneStep 2 with built-in flash and USB charging. Used for one trip. Includes a sealed pack of i-Type color film (8 shots).', 60.00, 'Hobbies', 'Used - Like New', 'demo.seller1@example.com', 'https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?auto=format&fit=crop&w=1200&q=80', 'Stanford, CA', now() - interval '75 hours'),
  ('a0000000-0000-4000-8000-000000000014', 'Vinyl Record Collection, 60+ LPs', 'Mostly classic rock, soul and jazz from the 70s and 80s. Sleeves show age but the records play well. Selling as one lot; list of titles on request.', 150.00, 'Entertainment', 'Used - Good', 'demo.seller3@example.com', 'https://images.unsplash.com/photo-1461360228754-6e81c478b882?auto=format&fit=crop&w=1200&q=80', 'Los Altos, CA', now() - interval '84 hours'),
  ('a0000000-0000-4000-8000-000000000015', '4-Person Camping Tent', 'Dome tent with a full rainfly, sets up in about 10 minutes. Used on three trips and dried before storing. All poles and stakes included.', 95.00, 'Garden & Outdoor', 'Used - Good', 'demo.seller4@example.com', 'https://images.unsplash.com/photo-1504280390367-361c6d9f38f4?auto=format&fit=crop&w=1200&q=80', 'Los Altos, CA', now() - interval '90 hours'),
  ('a0000000-0000-4000-8000-000000000016', 'LEGO Bricks, 5 lb Bulk Lot', 'About 5 pounds of genuine LEGO: mixed bricks, plates, wheels and a few minifigures. Washed and sorted by color into zip bags.', 45.00, 'Toys & Games', 'Used - Good', 'demo.seller2@example.com', 'https://images.unsplash.com/photo-1587654780291-39c9404d746b?auto=format&fit=crop&w=1200&q=80', 'Sunnyvale, CA', now() - interval '96 hours'),
  ('a0000000-0000-4000-8000-000000000017', 'Milwaukee M18 Cordless Drill with Battery', 'M18 compact 1/2-inch drill/driver with a 2.0Ah battery and charger. Used for a few weekend projects. Holds a charge well.', 110.00, 'Home Improvement', 'Used - Good', 'demo.seller3@example.com', 'https://images.unsplash.com/photo-1504148455328-c376907d081c?auto=format&fit=crop&w=1200&q=80', 'Mountain View, CA', now() - interval '100 hours'),
  ('a0000000-0000-4000-8000-000000000018', 'Black Leather Moto Jacket, Size M', 'Genuine lambskin leather with an asymmetric zip and quilted lining. Worn a handful of times. Fits true to size, men''s medium.', 120.00, 'Apparel', 'Used - Like New', 'demo.seller2@example.com', 'https://images.unsplash.com/photo-1551028719-00167b16eac5?auto=format&fit=crop&w=1200&q=80', 'San Mateo, CA', now() - interval '110 hours'),
  ('a0000000-0000-4000-8000-000000000019', 'PlayStation 5 Disc Edition', 'PS5 disc console with one DualSense controller and all original cables. Runs quiet and cool. Selling because I barely play.', 380.00, 'Entertainment', 'Used - Like New', 'demo.seller4@example.com', 'https://images.unsplash.com/photo-1606813907291-d86efa9b94db?auto=format&fit=crop&w=1200&q=80', 'San Mateo, CA', now() - interval '115 hours'),
  ('a0000000-0000-4000-8000-000000000020', 'Garden Trowel, Pruners and Potting Mix', 'Downsizing my balcony garden. Stainless trowel, bypass pruners, a hand rake, and an unopened 16 qt bag of potting mix.', 25.00, 'Garden & Outdoor', 'Used - Good', 'demo.seller1@example.com', 'https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=1200&q=80', 'Palo Alto, CA', now() - interval '120 hours'),
  ('a0000000-0000-4000-8000-000000000021', 'Nike Flyknit Running Shoes, Men''s 10', 'Red Flyknit runners, worn on maybe five runs. Clean soles, no odor. Original box included.', 65.00, 'Apparel', 'Used - Like New', 'demo.seller3@example.com', 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=1200&q=80', 'Palo Alto, CA', now() - interval '130 hours'),
  ('a0000000-0000-4000-8000-000000000022', 'Navy Laptop Backpack, Fits 15-inch', 'Water-resistant backpack with a padded laptop sleeve, two side bottle pockets and a luggage strap. Used for one quarter. Zippers work perfectly.', 35.00, 'Apparel', 'Used - Like New', 'demo.seller1@example.com', 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=1200&q=80', 'Stanford, CA', now() - interval '140 hours'),
  ('a0000000-0000-4000-8000-000000000023', 'Potted Aloe Succulent', 'Healthy aloe in a 5-inch mint ceramic pot with a drainage hole. Easy care: bright light and water every two weeks.', 12.00, 'Garden & Outdoor', 'New', 'demo.seller2@example.com', 'https://images.unsplash.com/photo-1485955900006-10f4d324d411?auto=format&fit=crop&w=1200&q=80', 'Redwood City, CA', now() - interval '150 hours'),
  ('a0000000-0000-4000-8000-000000000024', 'Mechanical Keyboard, Linear Red Switches', 'Full-size mechanical keyboard with hot-swap red switches and PBT keycaps in a retro color scheme. USB-C detachable cable included.', 85.00, 'Office Supplies', 'Used - Like New', 'demo.seller4@example.com', 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=1200&q=80', 'Stanford, CA', now() - interval '160 hours')
